// Nur der aktuelle Lauf, und nur was einem Menschen vorgelegt wird.
const text = Buffer.from($input.first().binary.data.data, 'base64').toString('utf8');
const heute = new Date().toISOString().slice(0, 10);
return text.trim().split('\n')
  .filter(Boolean)
  .map((z) => JSON.parse(z))
  .filter((e) => e.zeitpunkt.startsWith(heute))
  .filter((e) => e.vorlage !== 'archiv')
  .map((json) => ({ json }));

// FREIGABESCHRITT — hier wird nichts automatisch wirksam.
//
// Ersetze diesen Node durch den Kanal, über den DU entscheidest:
// E-Mail, Slack, oder n8n "Send and Wait for Response" für Zustimmen/Ablehnen.
// Die Freigabefelder im Protokoll (freigabe, freigegeben_von, freigegeben_am)
// sind dafür vorgesehen und bleiben bis dahin null.
return $input.all().map((i) => ({ json: {
  betreff: `[Steuer-Radar] ${i.json.vorlage === 'unklar' ? 'Unklar' : 'Relevant'}: ${i.json.titel}`,
  text: [
    i.json.titel,
    '',
    i.json.modellausgabe?.was_aendert_sich ?? '(keine gültige Modellausgabe)',
    i.json.modellausgabe?.bereiche?.length ? `Bereiche: ${i.json.modellausgabe.bereiche.join(', ')}` : '',
    i.json.modellausgabe?.wirksam_ab ? `Wirksam ab: ${i.json.modellausgabe.wirksam_ab}` : '',
    `Einstufung: ${i.json.vorlage} — ${i.json.grund}`,
    '',
    i.json.link,
  ].filter(Boolean).join('\n'),
  link: i.json.link,
} }));
